def transform(grid):
    h, w = len(grid), len(grid[0])
    # A uniform nonzero middle row/column divides two same-sized masks.
    for r in range(h):
        if r * 2 + 1 == h and len(set(grid[r])) == 1 and grid[r][0] != 0:
            half = r
            return [[2 if grid[i][j] != 0 and grid[r + 1 + i][j] != 0 else 0
                     for j in range(w)] for i in range(half)]
    for c in range(w):
        if c * 2 + 1 == w and len({grid[i][c] for i in range(h)}) == 1 and grid[0][c] != 0:
            half = c
            return [[2 if grid[i][j] != 0 and grid[i][c + 1 + j] != 0 else 0
                     for j in range(half)] for i in range(h)]
    raise ValueError('no centered uniform nonzero divider with equal-sized masks')
